import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';
import { MolecularlTestComponent } from './molecularl-test.component';

const routes: Routes = [
  {
    path: '',
    component: MolecularlTestComponent,
    data: {
      title: 'molecularl-test'
    }
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes) ,],
  exports: [RouterModule]
})
export class MolecularlTestRoutingModule {}