import { HttpErrorResponse } from '@angular/common/http';
import { Component, OnInit, SecurityContext } from '@angular/core';
import { NgForm } from '@angular/forms';
import { Router } from '@angular/router';
import { molecularl_test } from '../../model/molecularl_test';
import { MolecularlTestService } from '../../services/molecularl-test.service';

@Component({
  selector: 'app-molecularl-test',
  templateUrl: './molecularl-test.component.html',
  styleUrls: ['./molecularl-test.component.scss'],
})
export class MolecularlTestComponent implements OnInit {

  constructor(private moleculartestservice: MolecularlTestService, private router: Router) {

  }


  ngOnInit(): void {
    this.get_all();
  }

  molecularl_tests: molecularl_test[]
  content_laboratory: boolean;
  public get_all() {
    this.moleculartestservice.get_all_molecularl_test().subscribe(
      data => {
        if (data.status == 200) {
          this.molecularl_tests = data.body;
          this.content_laboratory = true;
        }
        else if (data.status == 204) {
          this.content_laboratory = false;
        }
      },
      (error: HttpErrorResponse) => {
        if (error.status == 403) {
          localStorage.clear();
          this.moleculartestservice.clear();
          this.router.navigateByUrl('/login');
        }
      }
    )
  }


  molecularl_test_update: molecularl_test;
  new_value = "";
  public update(molecularl_test: molecularl_test) {
    if (window.confirm('Are you sure')) {
      this.new_value = (<HTMLInputElement>document.getElementById("molecularl_test_update.test_TYPE")).value;
      molecularl_test.test_TYPE = this.new_value;
      this.moleculartestservice.update_molecularl_test(molecularl_test).subscribe(
        (response: string) => {
          this.get_all();
          this.alert('Molecular test successfully updated', 'warning');
        },
        (error: HttpErrorResponse) => {
          if (error) {
            console.log(error.message); console.log(error.status)
          }
        }
      )
    }
  }
  public set(molecularl_test: molecularl_test) {
    this.molecularl_test_update = molecularl_test;
    (<HTMLInputElement>document.getElementById("molecularl_test_update.test_TYPE")).value = molecularl_test.test_TYPE;

  }


  public delete(test: string) {
    if (window.confirm('Are you sure')) {
      this.moleculartestservice.delete_molecularl_test(test).subscribe(
        (response: string) => {
          this.get_all()
          this.alert('Molecular test successfully deleted', 'danger');
        }
        ,
        (error: HttpErrorResponse) => {
          if (error) { console.log(error.message); console.log(error.status) }
        })
    }
  }

  new_molecularl_test: molecularl_test;
  existe: boolean;
  n: boolean;
  add(molecularl_test: NgForm) {
    this.new_molecularl_test = molecularl_test.value;
    this.new_molecularl_test
    this.new_molecularl_test.loginuser = localStorage.getItem("current_user_id");
    this.moleculartestservice.add_molecularl_test(this.new_molecularl_test).subscribe(
      (response) => {
        if (response == "201") {
          this.existe = false;
          this.get_all();
          this.alert('Molecular test successfully added', 'primary');
          molecularl_test.resetForm();
          this.hide()
        }
        else if
          (response == "200") { this.existe = true; }
      },
      (error: HttpErrorResponse) => {
        if (error) {
          if (error.status == 403) {
            localStorage.clear();
            this.moleculartestservice.clear();
            this.router.navigateByUrl('/login');
          }
        }
      }
    )
  }

  hide() {
    let element: HTMLElement = document.getElementById('r') as HTMLElement;
    element.click();
  }

  cancel_add(molecularl_test: NgForm) {
    molecularl_test.resetForm();
    this.existe=false;
  }

  alertsDismiss: any = [];
  alert(msg: string, type: string) {
    this.alertsDismiss.push({
      type: type,
      msg: msg,
      timeout: 2500
    });
  }

}
