import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { CookieService } from 'ngx-cookie';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';
import {molecularl_test} from '../model/molecularl_test'

@Injectable({
  providedIn: 'root'
})
export class MolecularlTestService {

  constructor(private http: HttpClient ,private cookie : CookieService) { }

  private baseurl = environment.baseurl;

  public get_all_molecularl_test(): Observable<any> {
    return this.http.get(this.baseurl + "molecularl_test/all",{observe: 'response'});
  }

  public delete_molecularl_test(id: string): Observable<string> {
    return this.http.delete(this.baseurl + "molecularl_test/?id=" + id, { responseType: 'text' });
  }

  public add_molecularl_test(molecularl_test: molecularl_test): Observable<string> {
    return this.http.post(this.baseurl + "molecularl_test/save", molecularl_test, { responseType: 'text'});
  }

  public update_molecularl_test(molecularl_test: molecularl_test): Observable<string> {
    return this.http.post(this.baseurl + "molecularl_test/update", molecularl_test, { responseType: 'text' });
  }

  clear()
  {
    this.cookie.remove('token');
  }

}